using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace Aesthetik.SchemaFix
{
    public class AesthetikSchemaFixInstallerV3 : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null)
                {
                    WriteLog("[AesthetikSchemaFixV3] No ProjectX connection string found, trying alternatives...");
                    foreach (ConnectionStringSettings s in ConfigurationManager.ConnectionStrings)
                    {
                        WriteLog("[AesthetikSchemaFixV3] Found connection: " + s.Name);
                    }
                    return;
                }
                string connStr = cs.ConnectionString;
                WriteLog("[AesthetikSchemaFixV3] Using System.Data.SqlClient with connection: " + cs.Name);

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();
                    WriteLog("[AesthetikSchemaFixV3] Connection opened successfully");
                    string[] statements = new[]
                    {
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHold') ALTER TABLE SOOrder ADD UsrComplianceHold bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHoldReason') ALTER TABLE SOOrder ADD UsrComplianceHoldReason nvarchar(500) NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('BAccount') AND name = 'UsrDisablePayLink') ALTER TABLE BAccount ADD UsrDisablePayLink bit NULL"
                    };
                    foreach (string sql in statements)
                    {
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = sql;
                            cmd.ExecuteNonQuery();
                        }
                        string col = sql.Substring(sql.IndexOf("name = '") + 8);
                        col = col.Substring(0, col.IndexOf("'"));
                        WriteLog("[AesthetikSchemaFixV3] OK: " + col);
                    }
                }
                WriteLog("[AesthetikSchemaFixV3] All columns created successfully");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikSchemaFixV3] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikSchemaFixV3] Inner: " + ex.InnerException.Message);
            }
        }
    }
}

using System;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.SM;

namespace StudioB.Inquiry
{
    /// <summary>
    /// Read-only inquiry graph that exposes PX.SM.AuditHistory via BQL.
    /// Accessible via SOAP screen-based API at /Soap/SB205530.asmx
    /// or via Contract-Based API if registered as an endpoint entity.
    /// </summary>
    public class StudioBAuditInquiry : PXGraph<StudioBAuditInquiry>
    {
        public PXSelect<
            AuditHistory,
            Where<AuditHistory.screenID, IsNotNull>,
            OrderBy<Desc<AuditHistory.changeDate>>
        > AuditRecords;
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.Setup
{
    /// <summary>
    /// One-time setup: populates the StudioBAuditTrail GI with result columns
    /// and enables OData exposure. The GI data source (PX.SM.AuditHistory) was
    /// created via the UI; this plugin adds the result grid columns that the
    /// UI field selector blocks for system DACs.
    ///
    /// Safe to re-run: uses IF NOT EXISTS guards on all inserts.
    /// </summary>
    public class StudioBAuditGISetup : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            WriteLog("[AuditGISetup] Starting GI result column setup...");

            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null)
                {
                    WriteLog("[AuditGISetup] No ProjectX connection string");
                    return;
                }

                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();

                    // Find the GI DesignID by name
                    string designId = null;
                    using (var cmd = new SqlCommand(
                        "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE Name = 'StudioBAuditTrail' AND CompanyID > 0",
                        conn))
                    {
                        var result = cmd.ExecuteScalar();
                        if (result != null && result != DBNull.Value)
                            designId = result.ToString();
                    }

                    if (string.IsNullOrEmpty(designId))
                    {
                        WriteLog("[AuditGISetup] GI 'StudioBAuditTrail' not found — create it in SM208000 first");
                        return;
                    }

                    WriteLog("[AuditGISetup] Found GI DesignID: " + designId);

                    // Verify the data source exists
                    int tableCount = 0;
                    using (var cmd = new SqlCommand(
                        "SELECT COUNT(*) FROM GITable WHERE DesignID = @did AND Name = 'PX.SM.AuditHistory' AND CompanyID > 0",
                        conn))
                    {
                        cmd.Parameters.AddWithValue("@did", designId);
                        tableCount = (int)cmd.ExecuteScalar();
                    }

                    if (tableCount == 0)
                    {
                        WriteLog("[AuditGISetup] Data source 'PX.SM.AuditHistory' not found in GI");
                        return;
                    }

                    WriteLog("[AuditGISetup] Data source verified (" + tableCount + " row(s))");

                    // Delete any existing result rows for this GI (clean slate)
                    using (var cmd = new SqlCommand(
                        "DELETE FROM GIResult WHERE DesignID = @did AND CompanyID > 0",
                        conn))
                    {
                        cmd.Parameters.AddWithValue("@did", designId);
                        int deleted = cmd.ExecuteNonQuery();
                        WriteLog("[AuditGISetup] Cleared " + deleted + " existing result rows");
                    }

                    // Insert result columns
                    string[] fields = new[]
                    {
                        "ScreenID",
                        "Operation",
                        "ChangeDate",
                        "UserName",
                        "TableName",
                        "BatchID",
                        "ChangeID",
                        "CombinedKey",
                        "ModifiedFields"
                    };

                    for (int i = 0; i < fields.Length; i++)
                    {
                        // Use dynamic column discovery: get all column names from GIResult,
                        // then insert only the ones we need + defaults for the rest
                        using (var cmd = new SqlCommand(@"
                            -- Get a template row from any existing GI to discover required columns
                            -- Then insert our row with the same structure but our field values
                            DECLARE @cid INT = (SELECT TOP 1 CompanyID FROM GIDesign WHERE DesignID = @did AND CompanyID > 0);
                            INSERT INTO GIResult (CompanyID, DesignID, RowID, LineNbr, IsActive, ObjectName, Field, SchemaField,
                                                  SortOrder, IsVisible, Width, QuickFilter, FastFilter, DefaultNav, Caption,
                                                  CreatedByID, CreatedByScreenID, CreatedDateTime,
                                                  LastModifiedByID, LastModifiedByScreenID, LastModifiedDateTime)
                            VALUES (@cid, @did, NEWID(), @lineNbr, 1, 'AuditHistory', @field, NULL,
                                    @sortOrder, 1, 120, 0, 0, 0, @caption,
                                    '00000000-0000-0000-0000-000000000000', 'SM208000', GETUTCDATE(),
                                    '00000000-0000-0000-0000-000000000000', 'SM208000', GETUTCDATE()
                            )", conn))
                        {
                            cmd.Parameters.AddWithValue("@did", designId);
                            cmd.Parameters.AddWithValue("@lineNbr", i + 1);
                            cmd.Parameters.AddWithValue("@field", fields[i]);
                            cmd.Parameters.AddWithValue("@sortOrder", i + 1);
                            cmd.Parameters.AddWithValue("@caption", fields[i]);
                            cmd.ExecuteNonQuery();
                        }
                        WriteLog("[AuditGISetup] Added result column: " + fields[i]);
                    }

                    // Enable OData exposure
                    using (var cmd = new SqlCommand(
                        "UPDATE GIDesign SET ExposeViaOData = 1 WHERE DesignID = @did AND CompanyID > 0",
                        conn))
                    {
                        cmd.Parameters.AddWithValue("@did", designId);
                        int updated = cmd.ExecuteNonQuery();
                        WriteLog("[AuditGISetup] OData enabled: " + updated + " row(s) updated");
                    }

                    WriteLog("[AuditGISetup] Complete — " + fields.Length + " columns + OData enabled");
                }
            }
            catch (Exception ex)
            {
                WriteLog("[AuditGISetup] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AuditGISetup] Inner: " + ex.InnerException.Message);
            }
        }
    }
}
